//! An install this funes disagrees with is said on every read, CLI and MCP: a hook that asked for a
//! spool nothing writes (an install from before the spool), and a registered integration speaking
//! another contract (an install by another binary). Own test binary: it drives the CLI with its own
//! `$HOME` and `$FUNES_HOME`, handed to the child only.

mod support;

use serde_json::{json, Value};
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::path::Path;
use std::process::{Command, Output, Stdio};

fn funes(home: &Path, funes_home: &Path, args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_funes"))
        .args(args)
        .env("HOME", home)
        .env("FUNES_HOME", funes_home)
        .env("HF_HOME", support::hf_home())
        .env_remove("CODEX_HOME")
        // Piped, so the child sees no terminal: what a hook's run looks like.
        .stdin(Stdio::piped())
        .output()
        .unwrap()
}

fn stderr(out: &Output) -> String {
    String::from_utf8_lossy(&out.stderr).into_owned()
}

fn stdout(out: &Output) -> String {
    String::from_utf8_lossy(&out.stdout).into_owned()
}

/// Speak MCP to `funes mcp <memory>` over stdio, as an agent bound to `memory` launches it:
/// initialize, then call `status`. Returns the server's instructions and the tool's text.
fn mcp_status(home: &Path, funes_home: &Path, memory: &str) -> (String, String) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_funes"))
        .args(["mcp", memory])
        .env("HOME", home)
        .env("FUNES_HOME", funes_home)
        .env("HF_HOME", support::hf_home())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    let mut stdin = child.stdin.take().unwrap();
    let mut lines = BufReader::new(child.stdout.take().unwrap()).lines();
    let mut send = |message: Value| {
        writeln!(stdin, "{message}").unwrap();
    };
    let mut reply = |id: u64| -> Value {
        for line in lines.by_ref() {
            let message: Value = serde_json::from_str(&line.unwrap()).unwrap();
            if message["id"] == json!(id) {
                return message["result"].clone();
            }
        }
        panic!("no reply to request {id}");
    };

    send(json!({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {
        "protocolVersion": "2024-11-05", "capabilities": {},
        "clientInfo": {"name": "test", "version": "0"}}}));
    let instructions = reply(1)["instructions"].as_str().unwrap().to_string();
    send(json!({"jsonrpc": "2.0", "method": "notifications/initialized"}));
    send(json!({"jsonrpc": "2.0", "id": 2, "method": "tools/call", "params": {"name": "status", "arguments": {}}}));
    let status = reply(2)["content"][0]["text"].as_str().unwrap().to_string();

    drop(stdin);
    let _ = child.kill();
    let _ = child.wait();
    (instructions, status)
}

#[test]
fn a_stale_install_is_said_on_every_read_until_funes_add_runs_again() {
    let tmp = tempfile::tempdir().unwrap();
    let home = tmp.path().join("home");
    let funes_home = tmp.path().join("funes");
    fs::create_dir_all(&home).unwrap();
    fs::create_dir_all(&funes_home).unwrap();
    let stamp = funes_home.join("spool/bonnie.missing");

    // Nothing to say on a machine where nothing is installed.
    let quiet = funes(&home, &funes_home, &["status"]);
    support::assert_success(&quiet);
    assert!(!stderr(&quiet).contains("note:"), "{}", stderr(&quiet));

    // An old hook: `funes index --harness bonnie` off a terminal, with no spool to drain.
    let refused = funes(&home, &funes_home, &["index", "--harness", "bonnie"]);
    assert!(!refused.status.success());
    assert_eq!(
        stderr(&refused).lines().next(),
        Some(
            "Error: the bonnie integration does not match this version of funes. Re-run `funes add bonnie` to update it."
        )
    );
    assert!(stamp.is_file(), "the refusal leaves its stamp");

    // An integration another binary installed: its manifest speaks a contract this funes does not.
    let clyde = home.join(".funes/agents/clyde");
    fs::create_dir_all(&clyde).unwrap();
    fs::write(
        clyde.join("manifest.json"),
        r#"{"contract_version": 99, "id": "clyde", "label": "Clyde", "repo": "acme/funes-clyde"}"#,
    )
    .unwrap();

    // The CLI says both on stderr and keeps stdout as it was. The cure is a bare `funes add`, which
    // installs on the memory the host is bound to.
    let status = funes(&home, &funes_home, &["status"]);
    support::assert_success(&status);
    let err = stderr(&status);
    let notes = "note: the bonnie integration does not match this version of funes. Re-run `funes add bonnie` to update it.\n\
                 note: the clyde integration does not match this version of funes. Re-run `funes add clyde` to update it.\n";
    assert_eq!(err, notes);
    assert!(!stdout(&status).contains("note:"), "{}", stdout(&status));

    // `ask` reads the memory in-process before it borrows an agent, so it gets the same line — and
    // with no index it stops there, agent unasked.
    let asked = funes(&home, &funes_home, &["ask", "claude", "anything"]);
    assert!(stderr(&asked).starts_with(notes), "{}", stderr(&asked));

    // The MCP server says both in its instructions and ahead of every tool's text, whatever memory
    // it was started on.
    let team = tmp.path().join("team-memory");
    let (instructions, text) = mcp_status(&home, &funes_home, team.to_str().unwrap());
    assert!(instructions.contains(notes), "{instructions}");
    assert!(text.starts_with(notes), "{text}");
    let body = &text[notes.len()..];
    assert!(
        body.starts_with('\n') && body.len() > 1,
        "the tool's own text follows the notes after a blank line: {body:?}"
    );

    // `funes add bonnie` creates the spool; the next hook finds it and the stamp goes. `funes add
    // clyde` replaces the manifest.
    fs::create_dir_all(funes_home.join("spool/bonnie")).unwrap();
    let found = funes(&home, &funes_home, &["index", "--harness", "bonnie"]);
    support::assert_success(&found);
    assert!(!stamp.exists(), "found, so no longer missing");
    fs::write(
        clyde.join("manifest.json"),
        r#"{"contract_version": 1, "id": "clyde", "label": "Clyde", "repo": "acme/funes-clyde"}"#,
    )
    .unwrap();
    let quiet = funes(&home, &funes_home, &["status"]);
    support::assert_success(&quiet);
    assert!(!stderr(&quiet).contains("note:"), "{}", stderr(&quiet));
}

//! `funes ask` with no agent CLI on PATH: a hard error naming the missing binary and suggesting
//! the other agent — unlike `add`, ask has no partial success to fall back on. Its own binary
//! because it clears the process-global `$PATH`, and cargo runs a file's tests concurrently —
//! any other test resolving binaries would race it.

#[tokio::test]
async fn ask_errors_when_the_agent_cli_is_missing() {
    std::env::set_var("PATH", "");

    let err = funes::commands::ask::claude("q".into(), funes::memory::Memory::local())
        .await
        .unwrap_err()
        .to_string();
    assert!(err.contains("`claude` isn't on PATH"), "{err}");
    assert!(err.contains("funes ask codex"), "suggests the other agent: {err}");

    let err = funes::commands::ask::preflight("codex").unwrap_err().to_string();
    assert!(err.contains("`codex` isn't on PATH"), "{err}");
    assert!(err.contains("funes ask claude"), "suggests the other agent: {err}");
}

//! Gated live test: a first push from a local memory with no rows gives the remote its embedding
//! model, and the next push appends onto it. Publishes to a unique scratch path on the shared test
//! dataset, then deletes it. No real data.
//!
//! Skipped unless `HF_FUNES_TEST_TOKEN` is set AND `trufflehog` is on PATH (the second push scans
//! its row). To run:
//!
//!   export HF_FUNES_TEST_TOKEN=<your HF token>
//!   RUST_MIN_STACK=16777216 cargo test --test push_model_first -- --nocapture

use std::io::Write;
use std::process::Command;
use std::time::{SystemTime, UNIX_EPOCH};

use funes::commands::index;
use funes::commands::push::{self, Confirm};
use funes::inference::EmbeddingModel;
use funes::memory::{dataset, Memory, MemoryState};
use hf_hub::HFClient;

const OWNER: &str = "optimum-internal-testing";
const NAME: &str = "funes-test";

fn never_asked(_label: &str, _chunks: usize, _why: push::Disjoint) -> bool {
    panic!("a push of no chunks asks nothing");
}

/// The remote's model and row count, when it holds a dataset.
async fn remote_model_and_rows(uri: &str) -> Option<(EmbeddingModel, usize)> {
    match Memory::parse(uri).state().await {
        Ok(MemoryState::Ready(ds)) => Some((
            dataset::embedding_model(&ds).unwrap(),
            ds.count_rows(None).await.unwrap(),
        )),
        _ => None,
    }
}

#[tokio::test]
async fn a_first_push_with_no_rows_gives_the_remote_its_model() {
    let token = std::env::var("HF_FUNES_TEST_TOKEN")
        .unwrap_or_default()
        .trim()
        .to_string();
    if token.is_empty() {
        eprintln!("skip: HF_FUNES_TEST_TOKEN not set");
        return;
    }
    if !Command::new("trufflehog")
        .arg("--version")
        .output()
        .is_ok_and(|o| o.status.success())
    {
        eprintln!("skip: trufflehog not installed (push's secret gate is fail-closed)");
        return;
    }
    std::env::set_var("HF_TOKEN", &token);
    let repo = HFClient::builder().token(token).build().unwrap().dataset(OWNER, NAME);
    let nanos = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let prefix = format!("_synctest/{}-{nanos}", std::process::id());
    let uri = format!("hf://datasets/{OWNER}/{NAME}/{prefix}/lancedb");

    let home = tempfile::tempdir().unwrap();
    std::env::set_var("FUNES_HOME", home.path());
    let e5 = EmbeddingModel::MultilingualE5Small;
    index::ensure_local_memory(e5).await.unwrap();
    let created = push::run_push(Memory::parse(&uri), false, Confirm::Ask(never_asked), &[]).await;
    let after_create = remote_model_and_rows(&uri).await;

    let src = tempfile::tempdir().unwrap();
    let mut f = std::fs::File::create(src.path().join("sess.funes.jsonl")).unwrap();
    writeln!(
        f,
        r#"{{"format":1,"session_id":"sess","cwd":"/synctest/proj","turn_uuid":"s1","seq":0,"ts":"2026-02-01T00:00:00Z","role":"user","blocks":[{{"block_type":"text","text":"给表加上索引"}}],"harness":"claude"}}"#
    )
    .unwrap();
    index::run_index(src.path(), false, None).await.unwrap();
    let appended = push::run_push(Memory::parse(&uri), false, Confirm::Yes, &[]).await;
    let after_append = remote_model_and_rows(&uri).await;

    // Cleanup before asserting, so a failed assertion can't leave the scratch path behind.
    let _ = repo
        .delete_folder()
        .path_in_repo(prefix.clone())
        .commit_message("cleanup funes first-push model test")
        .send()
        .await;

    let report = created.unwrap().report;
    assert!(report.contains(&format!("created with {}", e5.id())), "{report}");
    assert_eq!(after_create, Some((e5, 0)));
    let report = appended.unwrap().report;
    assert!(report.contains("pushed 1 chunks"), "{report}");
    assert_eq!(after_append, Some((e5, 1)));
}

// Shared by the test binaries that drive `funes`; each uses the subset it needs.
#![allow(dead_code)]

use std::collections::HashMap;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};
use std::sync::Arc;

use arrow_array::types::Float32Type;
use arrow_array::{ArrayRef, FixedSizeListArray, Int64Array, RecordBatch, RecordBatchIterator, StringArray};
use arrow_schema::{Field, Schema};
use funes::commands::recall;
use funes::home;
use funes::inference::{self, EmbeddingModel};
use funes::memory::{dataset, Memory};
use hf_hub::{HFError, HFRepository, RepoTypeDataset};
use lance::Dataset;

/// The model cache the embedder and reranker read, for a run whose `$HOME` is fake.
pub fn hf_home() -> PathBuf {
    std::env::var_os("HF_HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(std::env::var_os("HOME").expect("a home")).join(".cache/huggingface"))
}

pub fn assert_success(output: &Output) {
    assert!(
        output.status.success(),
        "status: {:?}\nstdout:\n{}\nstderr:\n{}",
        output.status,
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}

/// Whether `bin arg` runs and succeeds: a tool a gated test needs is on `PATH`.
pub fn tool_ok(bin: &str, arg: &str) -> bool {
    Command::new(bin)
        .arg(arg)
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

/// A turns file under `tests/fixtures/funes_jsonl`.
pub fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/funes_jsonl")
        .join(name)
}

/// Write `session`'s turns file under `source`: one user text turn a second per text, the n-th
/// turn `t<n>`, so a longer list grows the same session.
pub fn write_session(source: &Path, session: &str, texts: &[impl AsRef<str>]) {
    let mut f = std::fs::File::create(source.join(format!("{session}.funes.jsonl"))).unwrap();
    for (i, text) in texts.iter().enumerate() {
        let turn = serde_json::json!({
            "format": 1,
            "session_id": session,
            "cwd": "/home/u/dev/demo",
            "turn_uuid": format!("t{i}"),
            "seq": i,
            "ts": format!("2026-01-01T00:00:{i:02}Z"),
            "role": "user",
            "blocks": [{"block_type": "text", "text": text.as_ref()}],
            "harness": "claude",
        });
        writeln!(f, "{turn}").unwrap();
    }
}

/// Write `test-session-0001` under `source`: a question, an answer that runs `cargo test`, and the
/// run's result. Returns the session id and the `workdir` facet its munged `cwd` gives.
pub fn write_transcript(source: &Path) -> (String, String) {
    let workdir = "-home-u-dev-demo";
    let session = "test-session-0001";
    let mut f = std::fs::File::create(source.join(format!("{session}.funes.jsonl"))).unwrap();
    let lines = [
        r#"{"format":1,"session_id":"test-session-0001","cwd":"/home/u/dev/demo","turn_uuid":"t1","seq":0,"ts":"2026-01-01T00:00:00Z","role":"user","blocks":[{"block_type":"text","text":"how do we parse transcripts into turns"}],"harness":"claude"}"#,
        r#"{"format":1,"session_id":"test-session-0001","cwd":"/home/u/dev/demo","turn_uuid":"t2","parent_uuid":"t1","seq":1,"ts":"2026-01-01T00:00:05Z","role":"assistant","blocks":[{"block_type":"text","text":"We parse each JSONL line into a turn with typed blocks."},{"block_type":"tool_use","text":"{\"command\":\"cargo test\"}","tool_name":"Bash","tool_use_id":"c1"}],"harness":"claude"}"#,
        r#"{"format":1,"session_id":"test-session-0001","cwd":"/home/u/dev/demo","turn_uuid":"t3","parent_uuid":"t2","seq":2,"ts":"2026-01-01T00:00:10Z","role":"user","blocks":[{"block_type":"tool_result","text":"22 passed","tool_name":"Bash","tool_use_id":"c1"}],"harness":"claude"}"#,
    ];
    for l in lines {
        writeln!(f, "{l}").unwrap();
    }
    (session.to_string(), workdir.to_string())
}

/// The rows the local memory holds.
pub async fn stored_rows() -> usize {
    let ds = dataset::open(&dataset::table_uri(home::memory_dir()), Default::default())
        .await
        .expect("the memory exists");
    dataset::scan_rows(&ds, &["id"], None, None)
        .await
        .unwrap()
        .iter()
        .map(|b| b.num_rows())
        .sum()
}

/// The chunk count `status` reports for the local memory.
pub async fn chunk_count() -> usize {
    let s = recall::status(Memory::local()).await.unwrap();
    s.lines()
        .find_map(|l| l.strip_prefix("chunks: "))
        .and_then(|n| n.trim().parse().ok())
        .expect("status reports a chunk count")
}

/// `funes index <source>` as a child process, with `home` as its `$FUNES_HOME`.
pub fn index(home: &Path, source: &Path) {
    let output = Command::new(env!("CARGO_BIN_EXE_funes"))
        .arg("index")
        .arg(source)
        .env("FUNES_HOME", home)
        .output()
        .unwrap();
    assert_success(&output);
}

/// The local memory under `home`.
pub async fn open_memory(home: &Path) -> Dataset {
    dataset::open(&dataset::table_uri(home.join("memory")), HashMap::new())
        .await
        .unwrap()
}

/// The fragments the local memory under `home` spans.
pub async fn fragments(home: &Path) -> usize {
    open_memory(home).await.get_fragments().len()
}

/// Index a one-turn session `s1` from `source` into the local memory under `home`, then append its
/// rows 257 more times, each its own fragment, and index them all: 258 small indexed fragments.
pub async fn index_fragmented(home: &Path, source: &Path) {
    write_session(source, "s1", &["a memory split into many small fragments"]);
    index(home, source);
    let mut ds = open_memory(home).await;
    let rows = dataset::scan_rows(&ds, &[], None, None).await.unwrap();
    let schema = Arc::new(Schema::from(ds.schema()));
    for _ in 0..257 {
        let reader = RecordBatchIterator::new(rows.clone().into_iter().map(Ok), schema.clone());
        ds.append(reader, None).await.unwrap();
    }
    dataset::build_indexes(&mut ds, |_| {}).await.unwrap();
    assert_eq!(fragments(home).await, 258);
}

/// A recall of the remote memory at `uri`, or the error it gave as the reply.
pub async fn recall_remote(uri: &str, query: &str) -> String {
    recall::recall(Memory::parse(uri), query.into(), 5, 30, 0, Default::default())
        .await
        .unwrap_or_else(|e| format!("<recall error: {e}>"))
}

/// The repo-root README, or None when the repo has none. Any other failure panics: a transport
/// error must fail the test loudly, not masquerade as "no README".
pub async fn root_readme(repo: &HFRepository<RepoTypeDataset>) -> Option<String> {
    match repo.download_file_to_bytes().filename("README.md").send().await {
        Ok(bytes) => Some(String::from_utf8_lossy(&bytes).into_owned()),
        Err(HFError::EntryNotFound { .. }) => None,
        Err(e) => panic!("querying the repo-root README: {e}"),
    }
}

pub fn files_containing(dir: &Path, needle: &str) -> Vec<PathBuf> {
    walkdir::WalkDir::new(dir)
        .into_iter()
        .map(|e| e.unwrap().into_path())
        .filter(|p| p.is_file())
        .filter(|p| {
            std::fs::read(p)
                .unwrap()
                .windows(needle.len())
                .any(|w| w == needle.as_bytes())
        })
        .collect()
}

/// Sessions are `s-0`, `s-1`, …, one per text.
pub async fn memory_of(model: EmbeddingModel, texts: &[&str], memory: &Path) {
    let memory = memory.to_string_lossy().into_owned();
    let n = texts.len();
    let embedded = inference::embedder(model).unwrap().embed(texts).unwrap();
    let ids: Vec<String> = (0..n).map(|i| format!("row-{i}")).collect();
    let sessions: Vec<String> = (0..n).map(|i| format!("s-{i}")).collect();
    let string = |values: Vec<Option<&str>>| -> ArrayRef { Arc::new(StringArray::from(values)) };
    let number = |values: Vec<i64>| -> ArrayRef { Arc::new(Int64Array::from(values)) };
    let vectors = FixedSizeListArray::from_iter_primitive::<Float32Type, _, _>(
        embedded.into_iter().map(|v| Some(v.into_iter().map(Some))),
        dataset::DIM,
    );
    let columns: Vec<(&str, ArrayRef)> = vec![
        ("id", string(ids.iter().map(|s| Some(s.as_str())).collect())),
        ("text", string(texts.iter().copied().map(Some).collect())),
        (
            "session_id",
            string(sessions.iter().map(|s| Some(s.as_str())).collect()),
        ),
        ("workdir", string(vec![Some("demo"); n])),
        ("turn_uuid", string(vec![Some("turn-0"); n])),
        ("parent_uuid", string(vec![None; n])),
        ("seq", number(vec![0; n])),
        ("ts", string(vec![Some("2026-01-01T00:00:00Z"); n])),
        ("role", string(vec![Some("user"); n])),
        ("block_type", string(vec![Some("text"); n])),
        ("tool_name", string(vec![None; n])),
        ("source_path", string(vec![Some("zh.funes.jsonl"); n])),
        ("block_idx", number(vec![0; n])),
        ("split_idx", number(vec![0; n])),
        ("vector", Arc::new(vectors)),
        ("harness", string(vec![Some("codex"); n])),
        ("repo", string(vec![Some(""); n])),
    ];
    let schema = Arc::new(Schema::new_with_metadata(
        columns
            .iter()
            .map(|(name, array)| Field::new(*name, array.data_type().clone(), true))
            .collect::<Vec<_>>(),
        HashMap::from([("embedding_model".to_string(), model.id().to_string())]),
    ));
    let batch = RecordBatch::try_new(schema.clone(), columns.into_iter().map(|(_, array)| array).collect()).unwrap();
    let reader = RecordBatchIterator::new([Ok(batch)], schema);
    let mut ds = Dataset::write(reader, &dataset::table_uri(&memory), None)
        .await
        .unwrap();
    dataset::build_indexes(&mut ds, |_| {}).await.unwrap();
}

//! Gated live test: the read-through cache behind remote reads. It publishes a synthetic memory to
//! a throwaway repo of its own (created and deleted here), so no other writer moves the head between
//! the two recalls. A first recall over `hf://` downloads the index + touched fragments into an
//! isolated HF cache; a second one is served from that cache and leaves it unchanged.
//!
//! Skipped unless `HF_FUNES_TEST_TOKEN` is set (it provides `HF_TOKEN`) AND `trufflehog` is on
//! PATH (push's pre-publish gate is fail-closed) — and skipped with a note if the token cannot
//! create a scratch repo under the test org. Needs a bigger thread stack than the default. To
//! run:
//!
//!   export HF_FUNES_TEST_TOKEN=<your HF token>
//!   RUST_MIN_STACK=16777216 cargo test --test remote_cache -- --nocapture

mod support;

use std::path::Path;
use std::time::{SystemTime, UNIX_EPOCH};

use funes::commands::push::Confirm;
use funes::memory::Memory;
use hf_hub::{HFClient, RepoTypeDataset};

const OWNER: &str = "optimum-internal-testing";
const MARKER: &str = "CACHESMOKE";

/// (entry count, total bytes) under `dir`, recursively.
fn cache_footprint(dir: &Path) -> (usize, u64) {
    let (mut entries, mut bytes) = (0usize, 0u64);
    let mut stack = vec![dir.to_path_buf()];
    while let Some(d) = stack.pop() {
        let Ok(rd) = std::fs::read_dir(&d) else { continue };
        for e in rd.flatten() {
            match std::fs::symlink_metadata(e.path()) {
                Ok(m) if m.is_dir() => stack.push(e.path()),
                Ok(m) => {
                    entries += 1;
                    if m.is_file() {
                        bytes += m.len();
                    }
                }
                _ => {}
            }
        }
    }
    (entries, bytes)
}

async fn recall(uri: &str) -> anyhow::Result<String> {
    funes::commands::recall::recall(Memory::parse(uri), MARKER.to_string(), 5, 30, 0, Default::default()).await
}

#[tokio::test]
async fn warm_recall_is_served_from_cache_without_downloading() {
    // In CI, an unset/fork secret expands to "" (env::var returns Ok("")), which must also skip.
    let token = std::env::var("HF_FUNES_TEST_TOKEN")
        .unwrap_or_default()
        .trim()
        .to_string();
    if token.is_empty() {
        eprintln!("skip: HF_FUNES_TEST_TOKEN not set");
        return;
    }
    if !support::tool_ok("trufflehog", "--version") {
        eprintln!("skip: trufflehog not installed (push's secret gate is fail-closed)");
        return;
    }
    // funes' Memory::open authenticates via HF_TOKEN.
    std::env::set_var("HF_TOKEN", &token);
    let client = HFClient::builder().token(token).build().unwrap();

    let home = tempfile::tempdir().unwrap();
    let src = tempfile::tempdir().unwrap();
    std::env::set_var("FUNES_HOME", home.path());
    support::write_session(src.path(), "sess", &[format!("{MARKER} the only turn")]);
    funes::commands::index::run_index(src.path(), false, None)
        .await
        .unwrap();

    // Unique repo name so concurrent/repeated runs don't collide.
    let nanos = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let name = format!("funes-test-cache-{}-{nanos}", std::process::id());
    if let Err(e) = funes::hub::create_dataset_repo(OWNER, &name).await {
        eprintln!("skip: cannot create a scratch repo under {OWNER}: {e}");
        return;
    }
    let uri = format!("hf://datasets/{OWNER}/{name}");
    let push = funes::commands::push::run_push(Memory::parse(&uri), false, Confirm::Yes, &[]).await;

    // Isolate the hf-hub cache to a fresh dir, so "cold" is a genuine first download and "warm"
    // can't be served by an entry left over from another run.
    let cache = tempfile::tempdir().unwrap();
    std::env::set_var("HF_HUB_CACHE", cache.path());
    let before = cache_footprint(cache.path());

    // Cold: the read wrapper downloads the index + touched fragments into the cache.
    let cold = recall(&uri).await;
    let after_cold = cache_footprint(cache.path());

    // Warm: same head commit ⇒ every file is already cached ⇒ the cache stays as it was.
    let warm = recall(&uri).await;
    let after_warm = cache_footprint(cache.path());

    // Cleanup before asserting, so a failed assertion can't leave the scratch repo behind.
    let _ = client
        .delete_repository()
        .repo_id(format!("{OWNER}/{name}"))
        .repo_type(RepoTypeDataset)
        .send()
        .await;

    push.expect("publishing the scratch memory");
    assert_eq!(before, (0, 0), "cache must start empty");
    let cold = cold.expect("cold recall");
    assert!(cold.contains(MARKER), "cold recall should surface the marker: {cold}");
    assert!(
        after_cold.0 > 0,
        "cold recall must populate the cache, got {after_cold:?}"
    );
    let warm = warm.expect("warm recall");
    assert!(warm.contains(MARKER), "warm recall should surface the marker: {warm}");
    assert_eq!(
        after_warm, after_cold,
        "warm recall must be served from the cache — cache changed: cold={after_cold:?} warm={after_warm:?}"
    );
}

//! `funes add <agent>` / `funes remove <agent>`: the registry ([`registry`]) that resolves an agent
//! id to an installed integration and runs it, plus the two helpers it needs. Every agent is an
//! integration script; funes's knowledge of one is the lookup.

pub mod registry;

use anyhow::{Context, Result};
use std::path::Path;

use crate::traces::spool;

/// What a read says when this funes and an install on this machine disagree, one `note:` line per
/// case, or `None`: a hook asked for a spool nothing writes (an install from before the spool), or a
/// registered integration speaks another contract (an install by another binary). The cure is the
/// same, `funes add <id>` again, which installs on the memory the host is bound to — and funes
/// knows no agent here, only what asked and what is registered.
pub fn stale_install_notice() -> Option<String> {
    let line = |id: &str| {
        format!("the {id} integration does not match this version of funes. Re-run `funes add {id}` to update it.")
    };
    let mut lines: Vec<String> = spool::missing().iter().map(|id| line(id)).collect();
    if let Ok(root) = registry::default_root() {
        lines.extend(registry::mismatched(&root).iter().map(|(id, _)| line(id)));
    }
    (!lines.is_empty()).then(|| lines.iter().map(|line| format!("note: {line}\n")).collect())
}

/// Render an argv as a copy/paste-safe POSIX shell command.
pub(crate) fn shell_command<S: AsRef<str>>(program: &str, args: &[S]) -> String {
    std::iter::once(program)
        .chain(args.iter().map(AsRef::as_ref))
        .map(shell_arg)
        .collect::<Vec<_>>()
        .join(" ")
}

fn shell_arg(arg: &str) -> String {
    if !arg.is_empty()
        && arg
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"_@%+=:,./-".contains(&b))
    {
        arg.to_string()
    } else {
        format!("'{}'", arg.replace('\'', "'\"'\"'"))
    }
}

/// Remove one exact funes-owned tree without following a symlink at the tree root.
pub(crate) fn remove_tree(path: &Path) -> Result<()> {
    match std::fs::symlink_metadata(path) {
        Ok(meta) if meta.file_type().is_symlink() || !meta.is_dir() => match std::fs::remove_file(path) {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(e) => Err(anyhow::Error::new(e).context(format!("removing {}", path.display()))),
        },
        Ok(_) => std::fs::remove_dir_all(path).with_context(|| format!("removing {}", path.display())),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(e) => Err(anyhow::Error::new(e).context(format!("inspecting {}", path.display()))),
    }
}

