        Default::default(),
    )
    .await
    .expect_err("recall with no index should error, not return canned content")
    .to_string();
    assert!(err.contains("funes add"), "recall should point at funes add: {err}");

    // status: informational — reports no index and points at the onboarding command (does not error).
    let status = funes::commands::recall::status(Memory::local()).await.unwrap();
    assert!(
        status.contains("no index yet"),
        "status should report no index: {status}"
    );
    assert!(
        status.contains("funes add"),
        "status should point at funes add: {status}"
    );
}

//! The line between a pool reranked and a pool cut as fused, over a real index under a temp
//! `$FUNES_HOME`: the defaults sit under it, fewer hits from the same pool sit over it.

mod support;

use funes::commands::recall;
use funes::memory::Memory;

#[tokio::test]
async fn a_pool_near_the_hits_is_not_reranked() {
    let db_dir = tempfile::tempdir().unwrap();
    let source = tempfile::tempdir().unwrap();
    std::env::set_var("FUNES_HOME", db_dir.path());
    support::write_transcript(source.path());
    funes::commands::index::run_index(source.path(), false, None)
        .await
        .unwrap();
    let quiet = |_: &str| ();
    let query = "parse transcripts into turns";

    // The defaults: 8 hits from a pool of 30, under the line.
    let (_, hits) = recall::recall_hits(
        Memory::local(),
        query.into(),
        recall::DEFAULT_K,
        recall::DEFAULT_CANDIDATES,
        0,
        Default::default(),
        &quiet,
    )
    .await
    .unwrap();
    assert!(!hits.is_empty());
    for (hit, score) in &hits {
        assert_eq!(*score, hit.fused as f64, "the defaults keep the fused order");
    }

    // Fewer hits from the same pool: four times the hits, reranked.
    let (_, hits) = recall::recall_hits(Memory::local(), query.into(), 5, 30, 0, Default::default(), &quiet)
        .await
        .unwrap();
    assert!(
        hits.iter().any(|(hit, score)| *score != hit.fused as f64),
        "a pool several times the hits is reranked"
    );
}

//! A push receipt for a remote, with an empty local memory behind it: what a first push with
//! nothing indexed leaves. The local memory adds nothing to that remote's recall, and does not
//! fail it.

use funes::commands::{index, recall, target};
use funes::inference::EmbeddingModel;

#[tokio::test]
async fn an_empty_local_memory_adds_no_unpushed_pool() {
    let home = tempfile::tempdir().unwrap();
    std::env::set_var("FUNES_HOME", home.path());
    index::ensure_local_memory(EmbeddingModel::MultilingualE5Small)
        .await
        .unwrap();
    // The receipt push keeps for hf://datasets/acme/memory, holding no chunk.
    let receipt = home.path().join("pushed/hf___datasets_acme_memory");
    std::fs::create_dir_all(receipt.parent().unwrap()).unwrap();
    std::fs::write(&receipt, "").unwrap();

    let search = recall::Search::new("an index on the table".into(), 30, Default::default()).unwrap();
    let pool = target::unpushed(&search, "hf://datasets/acme/memory").await.unwrap();
    assert!(pool.is_none());
}
